class ConnectFour {
  constructor() {
    this.rows = 6;
    this.cols = 7;
    // Row 0 = bottom of board so drop scans upward to the first empty slot.
    this.board = Array.from({ length: 6 }, () => new Array(7).fill(''));
  }
  drop(col, color) {
    for (let r = 0; r < this.rows; r++) {
      if (this.board[r][col] === '') { this.board[r][col] = color; return r; }
    }
    return -1;                                  // column full — sentinel
  }
  winner() {
    // Only 4 directions — reverses would re-detect the same line from its other end.
    const dirs = [[0,1],[1,0],[1,1],[1,-1]];    // →, ↑, ↗, ↘
    for (let r = 0; r < this.rows; r++) {
      for (let c = 0; c < this.cols; c++) {
        const v = this.board[r][c];
        if (!v) continue;
        for (const [dr, dc] of dirs) {
          let k = 1;
          // Count consecutive matches in this direction, capped at 4.
          while (k < 4) {
            const nr = r + dr*k, nc = c + dc*k;
            if (nr < 0 || nr >= this.rows || nc < 0 || nc >= this.cols) break;
            if (this.board[nr][nc] !== v) break;
            k++;
          }
          if (k === 4) return v;
        }
      }
    }
    return '';
  }
}

